const b1ExampleTranslations = [
  "Mientras esperaba el tren, me encontré por casualidad con una antigua amiga.",
  "Perdí la conexión, así que pedí una alternativa.",
  "Creo que el final convence, aunque el ritmo es lento.",
  "La responsable explicó que entregaríamos el proyecto el viernes.",
  "Podríamos reducir el ruido del vecindario.",
  "A pesar del coste, reutilizar los materiales reduce los residuos.",
  "Si tuviera más tiempo, participaría en el proyecto."
];

function createB1Lesson(config, topic, topicIndex, lessonIndex, vocabulary, examples) {
  const grammar = config.grammar[topicIndex];
  const scene = topic.scenes[lessonIndex];
  const example = examples[topicIndex];
  const vocabularyIndex = (lessonIndex * 3) % vocabulary.length;
  const quizIndex = (lessonIndex * 3 + 1) % vocabulary.length;
  const fillWord = vocabulary[vocabularyIndex];
  const quizWord = vocabulary[quizIndex];
  const quizOptions = [
    quizWord.target,
    vocabulary[(quizIndex + 1) % vocabulary.length].target,
    vocabulary[(quizIndex + 2) % vocabulary.length].target
  ];

  return {
    id: `${topic.id}-${lessonIndex + 1}`,
    title: scene[0],
    minutes: 12,
    objective: scene[1],
    vocabulary,
    steps: [
      {
        type: "vocabulary",
        title: "Léxico para argumentar y narrar",
        instruction: "Estudia las expresiones en contexto. Observa qué conectores ayudan a organizar el relato o justificar una idea.",
        itemIds: vocabulary.map((word) => word.target)
      },
      {
        type: "grammar",
        title: grammar[0],
        explanation: grammar[1],
        pattern: grammar[2],
        examples: [
          { target: example.target, translation: example.translation },
          { target: examples[(topicIndex + 1) % examples.length].target, translation: examples[(topicIndex + 1) % examples.length].translation }
        ],
        tip: grammar[3]
      },
      {
        type: "fillBlank",
        title: "Recuperación de vocabulario",
        prompt: `¿Cómo se dice «${fillWord.translation}» en ${config.name}?`,
        answer: fillWord.target,
        acceptedAnswers: [fillWord.target],
        hint: `Repasa el vocabulario de «${topic.title}» y revisa cómo se usa en una frase.`
      },
      {
        type: "dialogue",
        title: "Intercambia y matiza una idea",
        scene: `Situación: ${scene[1]} Escucha la propuesta y elige una respuesta que permita continuar la conversación.`,
        turns: [{
          speaker: "Interlocutor",
          it: config.interaction[0],
          es: config.interaction[1],
          options: [
            { it: config.interaction[2], es: config.interaction[3], correct: true },
            { it: config.interaction[4], es: config.interaction[5], correct: false }
          ]
        }]
      },
      {
        type: "production",
        title: "Producción libre",
        prompt: `${scene[1]} Explica tu respuesta con dos razones, un ejemplo y un conector de contraste o consecuencia.`,
        frame: "Desde mi punto de vista, ___. En primer lugar, ___. Sin embargo / Por lo tanto, ___.",
        model: `${example.target} — ${example.translation}`,
        privacyNote: "Usa ejemplos ficticios o detalles que te sientas cómodo compartiendo. No necesitas grabarte."
      },
      {
        type: "multipleChoice",
        title: "Mini-quiz",
        prompt: `¿Qué palabra o expresión significa «${quizWord.translation}»?`,
        options: quizOptions,
        answer: quizWord.target,
        feedback: `«${quizWord.target}» significa «${quizWord.translation}». ${grammar[3]}`
      }
    ]
  };
}

function createB1Course(language, config) {
  const examples = config.examples.map((target, index) => ({
    target,
    translation: b1ExampleTranslations[index]
  }));
  const roadmap = b1Topics.map((topic, index) => ({
    id: topic.id,
    title: topic.title,
    canDo: topic.canDo,
    grammar: config.grammar[index][0],
    sounds: config.sounds,
    vocabulary: topic.vocabularyEs.join(", "),
    game: topic.scenes[index % topic.scenes.length][0]
  }));
  return {
    metadata: {
      language,
      languageName: config.name,
      supportLanguage: "es",
      speechLanguage: config.speech,
      level: "B1",
      audience: "Hispanohablantes con bases A2 que desean desenvolverse con autonomía en situaciones conocidas",
      estimatedMinutes: 760,
      design: "Siete unidades de narración, interacción, argumentación y producción autónoma con práctica y evaluación formativa",
      contentNote: "Material original de nivel B1 alineado con objetivos comunicativos del MCER; adaptar ejemplos regionales y validar con docentes."
    },
    roadmap,
    units: b1Topics.map((topic, topicIndex) => {
      const vocabulary = [
        ...config.words[topicIndex].split(",").map((target, index) => ({
          target: target.trim(),
          translation: topic.vocabularyEs[index]
        })),
        ...config.commonWords.flatMap((words) => words.split(",")).map((target, index) => ({
          target: target.trim(),
          translation: [
            "afrontar", "describir", "resultar", "lograr", "ocurrir",
            "a pesar de", "por consiguiente", "mientras que", "por un lado", "por otro lado"
          ][index]
        }))
      ];
      return {
        id: topic.id,
        title: topic.title,
        lessons: topic.scenes.map((_, lessonIndex) => {
          const count = 15;
          const start = Math.round((lessonIndex / (topic.scenes.length - 1)) * (vocabulary.length - count));
          return createB1Lesson(
            config,
            topic,
            topicIndex,
            lessonIndex,
            vocabulary.slice(start, start + count),
            examples
          );
        })
      };
    })
  };
}

window.MULTILINGUAL_B1_CURRICULA = Object.fromEntries(
  Object.entries(b1LanguageConfig).map(([language, config]) => [
    language,
    createB1Course(language, config)
  ])
);
window.MULTILINGUAL_B1_RESOURCES = Object.fromEntries(
  Object.entries(b1LanguageConfig).map(([language, config]) => [
    `${language}-b1`,
    {
      pronunciation: config.sounds,
      ipa: config.ipa,
      listening: "Escucha una vez para identificar la postura y una segunda vez para reconocer razones, ejemplos y conectores. Resume el mensaje con tus propias palabras.",
      pitfalls: config.pitfalls
    }
  ])
);
